// Gộp → khử trùng → lọc hợp kênh → xếp mới nhất → soạn BẢN TIN GỌN top 10.
const KW = ['lãi suất','vay','mua nhà','giá nhà','vàng','kim cương','thuế','tiết kiệm','đầu cơ','ngân hàng','bất động sản','tạm ứng','tỷ giá','usd','trái phiếu','lừa đảo','phí','tài khoản','đất','chung cư','bảo hiểm','trả góp'];
const HOURS = 30; const now = Date.now(); const seen = new Set();
let items = $input.all().map(i=>i.json).filter(it => {
  const link = it.link||it.guid||it.title; if(!link||seen.has(link)) return false; seen.add(link);
  const t = ((it.title||'')+' '+(it.contentSnippet||it.content||'')).toLowerCase();
  if(!KW.some(k=>t.includes(k))) return false;
  const ts = Date.parse(it.isoDate||it.pubDate||0); return !ts || (now-ts) < HOURS*3600*1000;
});
items.sort((a,b)=>Date.parse(b.isoDate||b.pubDate||0)-Date.parse(a.isoDate||a.pubDate||0));
items = items.slice(0,10);
const lines = items.map((it,i)=>{
  const sum = (it.contentSnippet||'').replace(/\s+/g,' ').slice(0,140);
  return `*${i+1}. ${it.title}*\n_${sum}_\n🔗 ${it.link}`;
});
const digest = `🗞 *RADAR TIN — Chuyện Tiền*  (${items.length} tin hợp kênh)\n\n` + lines.join('\n\n') + `\n\n👉 Anh chọn số nào thì nhắn Claude làm short.`;
return [{ json: { digest, count: items.length } }];
